import { TypingIndicator, Card } from "march/ui"

// gece kuşları: koyu temada, satır içi, mor noktalar yanıp söner
export function NightOwls() {
  return <Card m:theme="night">
    <TypingIndicator names={["Baykuş"]} variant="inline" motion="fade" m:color="brand-purple" />
  </Card>
}

import { TypingIndicator } from "march/ui"

// TypingIndicator'ın özellikleri: names, variant, text, label (kendi cümlen), dots (false ya da kendi öğen), motion, class
export function TypingIndicatorLab() {
  return <div sx={{ flex: "col", gap: 2 }}>
    <TypingIndicator class="lab-own" names={["Elif", "Can"]} variant="bubble" label={(n: readonly string[]) => `${n.join(" ve ")} karalıyor`} motion="none" />
    <TypingIndicator class="lab-nodots" names={["Deniz"]} variant="inline" dots={false} />
    <TypingIndicator class="lab-quiet" names={["Ada"]} text={false} />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { TypingIndicatorLab } from "./TypingIndicatorLab.tsx"

// TypingIndicatorLab'in testleri: kaydedince Testler sekmesinde çalışır
test("label kendi cümlesini yazar", () => {
  const s = renderTest(() => <TypingIndicatorLab />)
  expect(s.sees("Elif ve Can karalıyor")).toBe(true)
})

test("bir durum bölgesi (role=status)", () => {
  const s = renderTest(() => <TypingIndicatorLab />)
  expect(s.all("[role=status]").length).toBeGreaterThan(0)
})
